SELECT COALESCE(SUM(t.amount), 0)
FROM TRANSACTIONS t

WHERE t.user_id = #{userId}
  AND t.type = 'EXPENSE'
  AND t.category NOT IN ('CARD_WITHDRAWAL', 'SEND', 'INCOME', 'LOAN_REPAYMENT')
  AND t.transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT COALESCE(SUM(t.amount), 0)
FROM TRANSACTIONS t

WHERE t.user_id = #{userId}
  AND t.type = 'INCOME'
  AND t.category NOT IN ('CARD_WITHDRAWAL', 'SEND')
  AND t.transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END AS category, COALESCE(SUM(t.amount), 0) AS amount FROM TRANSACTIONS t
WHERE t.user_id = #{userId} AND t.type = 'EXPENSE' AND t.category NOT IN ('CARD_WITHDRAWAL', 'SEND', 'INCOME', 'LOAN_REPAYMENT') AND t.transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}
GROUP BY CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END ORDER BY amount DESC, category ASC

SELECT t.transaction_id AS transactionId, t.transaction_date AS date, t.type AS type, CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END AS category, t.amount AS amount, t.merchant_name AS merchantName FROM TRANSACTIONS t
WHERE t.user_id = #{userId} AND t.transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate} AND t.category NOT IN ('CARD_WITHDRAWAL', 'LOAN_REPAYMENT')
ORDER BY t.transaction_date DESC, t.transaction_time DESC, t.transaction_id DESC LIMIT #{condition.size} OFFSET #{condition.offset}

SELECT COUNT(*)
FROM TRANSACTIONS t

WHERE t.user_id = #{userId}
  AND t.transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}
  AND t.category NOT IN ('CARD_WITHDRAWAL', 'LOAN_REPAYMENT')
